def load():
    import os,glob,re
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
import numpy as np
inp=np.array(G['Demo pair 1 input']); out=np.array(G['Demo pair 1 output'])
def transform(g):
    g=np.array(g); h,w=g.shape; s=h//3
    r=[]
    for i in range(s):
        row=[]
        for j in range(s):
            b=g[3*i:3*i+3,3*j:3*j+3]
            cols=set(b.ravel())-{0,5}
            row.append(list(cols)[0] if len(cols)==1 else (0 if not cols else -1))
        r.append(row)
    return r
print(np.array(transform(G['Demo pair 1 input'])))
